package cl.bolsillo.app;
import org.json.*;

public class LearnedRulesTest {
 static int checks;
 static void yes(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static JSONObject evidence(int index)throws Exception{return new JSONObject().put("id","notice-"+index).put("key","android-bank-notification").put("at",100000L+index*1000L).put("merchant","NETFLIX.COM").put("source","bank.synthetic").put("label","MACH de prueba").put("last4","1234").put("type","expense").put("amount",4990).put("account","bank-mach").put("category","expense-7");}
 static JSONObject transaction(int index)throws Exception{return NativeSync.transaction("expense",4990,"bank-mach","","expense-7","Netflix","notification","notice-"+index).put("status","posted");}
 public static void main(String[] args)throws Exception{
  JSONObject d=Ledger.initial();String original=d.toString();yes(LearnedRules.match(d,evidence(1))==null,"empty rules do not invent a match");yes(d.toString().equals(original),"reading learning does not modify existing records");yes(LearnedRules.mode(d,true).equals("automatic")&&LearnedRules.mode(d,false).equals("review"),"existing registration preference preserved");
  LearnedRules.confirmed(d,evidence(1),transaction(1));JSONObject r=LearnedRules.list(d).getJSONObject(0);yes(r.getJSONArray("exampleIds").length()==1,"first explicit confirmation creates one example");LearnedRules.confirmed(d,evidence(1),transaction(1));yes(r.getJSONArray("exampleIds").length()==1,"same record confirmed again cannot teach twice");
  LearnedRules.confirmed(d,evidence(2).put("duplicateOf","existing-movement"),transaction(2));yes(r.getJSONArray("exampleIds").length()==1,"possible duplicates do not become training examples");
  LearnedRules.confirmed(d,evidence(2),transaction(2));yes(!LearnedRules.match(d,evidence(7)).ready,"two confirmations remain for review");LearnedRules.confirmed(d,evidence(3),transaction(3));LearnedRules.Match match=LearnedRules.match(d,evidence(7));yes(match.ready&&match.rule.getString("category").equals("expense-7"),"three distinct consistent confirmations allow the pattern");
  yes(!LearnedRules.match(d,evidence(7).put("amount",5990)).ready,"amount outside confirmed interval requires review");yes(!LearnedRules.match(d,evidence(7).put("account","")).ready,"missing bank/card assignment is never filled arbitrarily");yes(!LearnedRules.match(d,evidence(7).put("account","bank-bancoestado")).ready,"changed account requires review");yes(LearnedRules.match(d,evidence(7).put("last4","5678"))==null,"physical and virtual card patterns remain distinct");yes(LearnedRules.match(d,evidence(7).put("source","wallet.synthetic"))==null,"another notification app needs its own evidence");
  r.put("enabled",false);yes(LearnedRules.match(d,evidence(7))==null,"disabled pattern does not apply");r.put("enabled",true);d.put("learnedConfig",new JSONObject().put("mode","patterns").put("threshold",4));yes(!LearnedRules.match(d,evidence(7)).ready,"higher configured threshold takes effect");d.put("learnedConfig",new JSONObject().put("mode","review").put("threshold",3));yes(LearnedRules.mode(d,true).equals("review"),"explicit review mode overrides legacy auto setting");
  LearnedRules.confirmed(d,evidence(4),transaction(4).put("category","expense-4"));yes(r.optBoolean("conflict")&&!LearnedRules.match(d,evidence(7)).ready,"contradictory category suspends automatic validation");yes(LearnedRules.explanation(r).contains("4 confirmaciones"),"rule explanation shows number of distinct examples");
  JSONObject referenceData=Ledger.initial();LearnedRules.confirmed(referenceData,evidence(10).put("reference","bank-ref-123"),transaction(10));LearnedRules.confirmed(referenceData,evidence(11).put("reference","bank-ref-123"),transaction(11));yes(LearnedRules.list(referenceData).getJSONObject(0).getJSONArray("exampleIds").length()==1,"same transaction reference cannot teach twice");
  JSONObject generic=Ledger.initial();LearnedRules.confirmed(generic,evidence(1).put("merchant","Transferencia recibida"),transaction(1));yes(LearnedRules.list(generic).length()==0,"generic income or merchant text does not produce broad rules");
  JSONObject pending=Ledger.initial();LearnedRules.confirmed(pending,evidence(1),transaction(1).put("status","pending"));yes(LearnedRules.list(pending).length()==0,"unconfirmed ledger record does not train rules");Ledger.validate(d);yes(d.getJSONArray("transactions").length()==0,"training examples never create or change transactions");
  System.out.println("PASS: "+checks+" local learning checks; three distinct examples, contradictions, bounds, routing, duplicate exclusions and preference preservation");
 }
}
